import {AnimatePresence,motion} from 'framer-motion';
import {ArrowLeft,ArrowRight,ArrowUpRight,Check,ChevronRight,ChevronDown,Home,Package,Wallet,UserRound,Bell,MapPin,Navigation,Clock3,ShieldCheck,Headphones,Store,Phone,MessageCircle,FileText,CreditCard,Globe,LogOut,Settings,Bike,Truck,ScanLine,AlertTriangle,CheckCircle2,X,PawPrint,IndianRupee,Route,BatteryFull,Wifi,Signal,LockKeyhole,LoaderCircle,RefreshCw,Heart} from 'lucide-react';
