import RouteMap from './RouteMap';
type Panel={title:string;content:ReactNode};
const money=(n:number)=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pickupReasons=['Store closed','Order not ready','Item missing','Wrong package','Damaged package','Other'];
const deliveryReasons=['Customer unavailable','Address issue','Customer refused delivery','Package damaged','Payment problem'];
export default function RiderApp({initial,onNavigate}:{initial:Screen;onNavigate?:(s:Screen)=>void}){
 const [screen,setScreen]=useState<Screen>(initial);const [variant,setVariant]=useState('default');const [panel,setPanel]=useState<Panel|null>(null);const [toast,setToast]=useState('');const scroll=useRef<HTMLDivElement>(null);
 const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [showPassword,setShowPassword]=useState(false);const [createAccount,setCreateAccount]=useState(false);const [authError,setAuthError]=useState('');const [authMessage,setAuthMessage]=useState('');const [busy,setBusy]=useState(false);const [signedIn,setSignedIn]=useState(false);
 const [name,setName]=useState('Rahul Kumar');const [zone,setZone]=useState('Madhapur');const [language,setLanguage]=useState('English');const [vehicle,setVehicle]=useState('Scooter');const [documents,setDocuments]=useState<string[]>([]);const [bank,setBank]=useState({holder:'',account:'',confirm:'',ifsc:''});const [formError,setFormError]=useState('');
 const [checks,setChecks]=useState<string[]>([]);const [locationStatus,setLocationStatus]=useState('Not requested');const [notifications,setNotifications]=useState('Not requested');const [reason,setReason]=useState('');const [notes,setNotes]=useState('');const [submitted,setSubmitted]=useState(false);const [handoverOtp,setHandoverOtp]=useState('');const [dateFrom,setDateFrom]=useState('2026-10-01');const [dateTo,setDateTo]=useState('2026-10-29');const [historyFilter,setHistoryFilter]=useState('Today');const [statusFilter,setStatusFilter]=useState('Completed');const [earningsPeriod,setEarningsPeriod]=useState('Today');const [read,setRead]=useState<string[]>([]);const [paymentMethod,setPaymentMethod]=useState('Cash');const [cashConfirmed,setCashConfirmed]=useState(false);const [supportMessages,setSupportMessages]=useState<string[]>([]);
 useEffect(()=>{setScreen(initial);if(initial==='documents')setDocuments([]);setVariant('default');setFormError('');scroll.current?.scrollTo(0,0)},[initial]);
 useEffect(()=>onAuthStateChanged(auth,u=>setSignedIn(!!u)),[]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),3800);return()=>clearTimeout(timer)},[toast]);
 function go(next:Screen){setScreen(next);setVariant('default');setPanel(null);setFormError('');setSubmitted(false);scroll.current?.scrollTo({top:0,behavior:'instant'});onNavigate?.(next)}
 function toggle(key:string){setChecks(prev=>prev.includes(key)?prev.filter(x=>x!==key):[...prev,key])}
 const showInfo=(title:string,content:ReactNode)=>setPanel({title,content});
 const notConnected=(what:string)=>showInfo(what,<><Notice tone="amber">This design is not connected to a rider operations service.</Notice><p>No {what.toLowerCase()} has been sent or completed. Use this preview to review the flow.</p></>);
 function emailValid(){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){setAuthError('Enter a valid email address.');return false}return true}
 function authFailure(e:unknown){const code=(e as {code?:string}).code;setAuthError(code==='auth/email-already-in-use'?'An account already uses this email. Log in or reset your password.':code==='auth/weak-password'?'Choose a stronger password with at least 8 characters.':code==='auth/too-many-requests'?'Too many attempts. Please wait and try again.':code==='auth/operation-not-allowed'?'Email and password sign-in must be enabled in Firebase.':code==='auth/network-request-failed'?'Check your internet connection and try again.':code==='auth/invalid-email'?'Enter a valid email address.':code==='auth/user-disabled'?'This account is disabled. Contact support.':'The email or password is incorrect. Please try again.')}
 async function submitEmail(){setAuthError('');setAuthMessage('');if(!emailValid())return;if(!password||(createAccount&&password.length<8)){setAuthError(createAccount?'Use at least 8 characters for your password.':'Enter your password.');return}setBusy(true);try{if(createAccount){await createUserWithEmailAndPassword(auth,email.trim(),password)}else{await signInWithEmailAndPassword(auth,email.trim(),password)}setPassword('');go(createAccount?'registration':'home');setToast(createAccount?'Account created':'Signed in securely')}catch(e){authFailure(e)}finally{setBusy(false)}}
 async function resetPassword(){setAuthError('');setAuthMessage('');if(!emailValid())return;setBusy(true);try{await sendPasswordResetEmail(auth,email.trim());setAuthMessage('If an account exists for this email, you will receive a password reset link.')}catch(e){authFailure(e)}finally{setBusy(false)}}
 function maps(destination:string){window.open('https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(destination),'_blank','noopener,noreferrer')}
 function location(){setLocationStatus('Requesting…');if(!navigator.geolocation){setLocationStatus('Unavailable');return}navigator.geolocation.getCurrentPosition(()=>setLocationStatus('Allowed'),()=>setLocationStatus('Permission unavailable'),{timeout:10000})}
 function settings(){showInfo('Location & notifications',<><p>Open your browser’s site settings using the icon beside the address bar. Allow location and notifications for PetMeta Rider, then return here.</p><button className="rd-secondary" onClick={()=>{setPanel(null);location()}}>Check location again <RefreshCw size={16}/></button></>)}
 const title=screens.find(s=>s[0]===screen)?.[1]||'PetMeta Rider';const mainNav=!focused.includes(screen)&&!onboarding.includes(screen);const isHome=screen==='home'||screen==='online';
 let content:ReactNode=null;let action:ReactNode=null;
 const earningsBreakdown=<div className="rd-breakdown"><div><span>Base delivery pay</span><b>₹30.00</b></div><div><span>Distance pay · 4 km total</span><b>₹15.00</b></div><div className="rd-breakdown-total"><span>Total earnings</span><strong>₹45.00</strong></div><small>Illustrative earnings. No time-based bonus.</small></div>;
 const call=(who:string)=>showInfo('Call '+who,<><Notice>Protected calling</Notice><p>A masked call connection will be available when a real delivery is assigned. No customer or store phone number is exposed in this preview.</p></>);
 const variants=(options:[string,string][])=> <div className="rd-state-picker"><span>PREVIEW STATE</span><select aria-label="Preview state" value={variant} onChange={e=>{setVariant(e.target.value);setFormError('')}}><option value="default">Default</option>{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div>;
 const orderTop=<div className="rd-order-top"><span className="rd-kicker">ORDER {order.id}</span><Badge>Prepaid</Badge></div>;

 if(screen==='splash'){content=<div className="rd-splash"><div className="rd-splash-mark"><img src="/logo.jpg" alt="PetMeta"/><span>RIDER</span></div><div className="rd-splash-route"><Store/><div><i/><PawPrint size={19}/><i/></div><Home/></div><h1>Deliver care,<br/>one doorstep at a time.</h1><p>Good rides. Happy pets.</p><div className="rd-loading-bars"><i/><i/><i/></div></div>;action=<Primary onClick={()=>go('welcome')}>Let’s begin</Primary>}
 if(screen==='welcome'){content=<><div className="rd-welcome-hero"><img src="/rider/rider-hero.png" alt="PetMeta rider with yellow jacket, scooter and branded delivery bag"/><span className="rd-art-chip"><PawPrint size={14}/> A little care goes a long way.</span></div><Heading eyebrow="HELLO, DELIVERY PARTNER" title="Deliver pet essentials near you." description="Pick up local orders, complete deliveries, and track your earnings."/><Card><Row icon={<MapPin size={18}/>} title="Nearby orders" detail="Local stores. Familiar neighborhoods."/><Row icon={<Wallet size={18}/>} title="Clear earnings" detail="Know your earnings before every ride."/><Row icon={<Headphones size={18}/>} title="Rider support" detail="A helping hand along the way."/></Card><label className="rd-language"><Globe size={16}/><select aria-label="Preferred language" value={language} onChange={e=>setLanguage(e.target.value)}><option>English</option><option>తెలుగు</option><option>हिन्दी</option></select></label>{language!=='English'&&<Notice>Language preference selected. This design preview uses English screen copy.</Notice>}</>;action=<><Primary onClick={()=>go('login')}>Get started</Primary><button className="rd-bottom-link" onClick={()=>go('login')}>Already registered? <b>Log in</b></button></>}
 if(screen==='login'){content=<><div className="rd-auth-symbol"><LockKeyhole size={32}/><span><Check size={15}/></span></div><Heading eyebrow="YOUR NEXT CHAPTER STARTS HERE" title={createAccount?'Your next ride starts here.':'Welcome back, rider.'} description={createAccount?'Create your account with an email and password.':'Log in with your email and password to continue.'}/><form id="rider-email-form" onSubmit={e=>{e.preventDefault();submitEmail()}} noValidate><label className="rd-field">Email address<input type="email" autoComplete="email" autoCapitalize="none" spellCheck={false} placeholder="you@example.com" value={email} onChange={e=>{setEmail(e.target.value);setAuthError('')}}/></label><label className="rd-field">Password<div className="rd-password-field"><input aria-label="Password" type={showPassword?'text':'password'} autoComplete={createAccount?'new-password':'current-password'} placeholder={createAccount?'Create a password (8+ characters)':'Enter your password'} value={password} onChange={e=>{setPassword(e.target.value);setAuthError('')}}/><button type="button" aria-label={showPassword?'Hide password':'Show password'} aria-pressed={showPassword} onClick={()=>setShowPassword(p=>!p)}>{showPassword?'Hide':'Show'}</button></div></label>{!createAccount&&<button type="button" className="rd-text-button" onClick={()=>{setPassword('');setAuthError('');setAuthMessage('');go('otp')}}>Forgot password?</button>}{authError&&<Notice tone="red"><span role="alert">{authError}</span></Notice>}<div className="rd-security-note"><ShieldCheck size={15}/> Secure sign-in with Firebase.</div></form></>;action=<><Primary type="submit" form="rider-email-form" disabled={busy}>{busy?<><LoaderCircle className="rd-spin" size={18}/>Please wait...</>:createAccount?'Create account':'Log in'}</Primary><button disabled={busy} className="rd-bottom-link" onClick={()=>{setCreateAccount(v=>!v);setPassword('');setAuthError('')}}>{createAccount?'Already have an account?':'New to PetMeta Rider?'} <b>{createAccount?'Log in':'Create account'}</b></button></>}
 if(screen==='otp'){content=<><div className="rd-auth-symbol"><LockKeyhole size={32}/></div><Heading eyebrow="LET’S GET YOU BACK IN" title="Forgot your password?" description="Enter your email address and we’ll send a password reset link."/><form id="rider-reset-form" noValidate onSubmit={e=>{e.preventDefault();resetPassword()}}><label className="rd-field">Email address<input type="email" autoComplete="email" autoCapitalize="none" placeholder="you@example.com" value={email} onChange={e=>{setEmail(e.target.value);setAuthError('');setAuthMessage('')}}/></label>{authError&&<Notice tone="red"><span role="alert">{authError}</span></Notice>}{authMessage&&<Notice tone="green"><span role="status">{authMessage}</span></Notice>}</form></>;action=<><Primary type="submit" form="rider-reset-form" disabled={busy}>{busy?'Sending...':'Send reset link'}</Primary><button className="rd-bottom-link" onClick={()=>{setAuthError('');go('login')}}>Back to log in</button></>}
 if(screen==='registration'){content=<><Step n={1}/><Heading title="A little about you." description="Let’s set up your rider profile."/><UploadCard title="Profile photo" description="A clear, front-facing photo. JPG or PNG."/><label className="rd-field">Full name *<input value={name} onChange={e=>setName(e.target.value)} placeholder="As on your identity document"/></label><label className="rd-field">City *<select><option>Hyderabad</option></select></label><div className="rd-form-pair"><label className="rd-field">Delivery area *<select value={zone} onChange={e=>setZone(e.target.value)}><option>Madhapur</option><option>Kondapur</option><option>Gachibowli</option></select></label><label className="rd-field">Language *<select value={language} onChange={e=>setLanguage(e.target.value)}><option>English</option><option>Telugu</option><option>Hindi</option></select></label></div><label className="rd-field">Your vehicle *</label><div className="rd-vehicle-options">{['Bicycle','Scooter','Motorcycle'].map((v,i)=><button key={v} className={vehicle===v?'selected':''} onClick={()=>setVehicle(v)}>{i<2?<Bike/>:<Truck/>}<span>{v}</span>{vehicle===v&&<Check size={12}/>}</button>)}</div>{formError&&<Notice tone="red">{formError}</Notice>}</>;action=<Primary onClick={()=>{if(name.trim().length<2){setFormError('Enter your full name to continue.');return}go('documents')}}>Save and continue</Primary>}
 if(screen==='documents'){const required=vehicle==='Bicycle'?['Identity document','Rider selfie']:['Identity document','Rider selfie','Vehicle registration','Driving licence'];content=<><Step n={2}/><Heading title="Let’s verify your details." description="Keep your documents clear and all four corners visible."/><Notice><ShieldCheck size={16}/> Design preview: use sample files only. Nothing is uploaded.</Notice>{required.map(t=><UploadCard key={t} title={t} description={t==='Rider selfie'?'Take a well-lit photo without sunglasses.':'JPG, PNG or WebP · maximum 5 MB'} sensitive={t!=='Rider selfie'} onUploaded={uploaded=>setDocuments(p=>uploaded?[...new Set([...p,t])]:p.filter(x=>x!==t))}/>)}{variants([['review','Under review'],['correction','Needs correction']])}{variant==='review'&&<Notice tone="amber">Identity document · under review</Notice>}{variant==='correction'&&<Notice tone="red">Vehicle document is blurry. Replace it with a clearer photo.</Notice>}{formError&&<Notice tone="amber">{formError}</Notice>}</>;action=<Primary onClick={()=>{if(!required.every(t=>documents.includes(t))){setFormError('Select each required document before continuing.');return}go('bank')}}>Save and continue</Primary>}
 if(screen==='bank'){content=<><Step n={3}/><Heading title="Make every ride count." description="Add the account where you’d like to receive payouts."/><Notice><LockKeyhole size={17}/> Use sample details in this design preview. They are not stored or submitted.</Notice>{(['holder','account','confirm','ifsc'] as const).map((k,i)=><label className="rd-field" key={k}>{['Account holder name *','Bank account number *','Confirm account number *','IFSC code *'][i]}<input value={bank[k]} autoComplete="off" type={k==='account'?'password':'text'} inputMode={k==='account'||k==='confirm'?'numeric':undefined} placeholder={['Full name','9–18 digits','Re-enter account number','e.g. ABCD0123456'][i]} onChange={e=>setBank(p=>({...p,[k]:k==='ifsc'?e.target.value.toUpperCase():e.target.value}))}/></label>)}<Card><Row icon={<ShieldCheck size={20}/>} title="Verification pending" detail="Account details are reviewed after submission." aside={<Badge tone="amber">Pending</Badge>}/></Card>{formError&&<Notice tone="red"><span role="alert">{formError}</span></Notice>}</>;action=<Primary onClick={()=>{if(!bank.holder.trim()||!/^\d{9,18}$/.test(bank.account)){setFormError('Enter the account holder and a 9–18 digit account number.');return}if(bank.account!==bank.confirm){setFormError('Account numbers don’t match. Please check both fields.');return}if(!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(bank.ifsc)){setFormError('Enter a valid 11-character IFSC code.');return}showInfo('Review payout account',<><Notice>Account ending •••• {bank.account.slice(-4)} · {bank.ifsc}</Notice><p>These details pass local format checks. No bank verification or application submission has taken place.</p><Primary onClick={()=>{setBank({holder:'',account:'',confirm:'',ifsc:''});go('application')}}>View application preview</Primary></>)}}>Submit application</Primary>}
 if(screen==='application'){content=<><div className="rd-review-art"><img src="/rider/rider-hero.png" alt="PetMeta delivery partner"/></div><Heading eyebrow="APPLICATION STATUS · SAMPLE" title={variant==='correction'?'One little update needed.':'Your application is under review.'} description={variant==='correction'?'Your vehicle document needs a clearer photo.':'We’ll notify you when there’s an update. Thanks for your patience.'}/><Card><Row icon={<UserRound size={18}/>} title="Rider profile" aside={<Badge>Complete</Badge>}/><Row icon={<ShieldCheck size={18}/>} title="Identity verification" aside={<Badge tone="amber">Under review</Badge>}/><Row icon={<Bike size={18}/>} title="Vehicle documents" aside={<Badge tone={variant==='correction'?'red':'amber'}>{variant==='correction'?'Needs correction':'Under review'}</Badge>}/><Row icon={<CreditCard size={18}/>} title="Payout account" aside={<Badge tone="muted">Pending</Badge>}/></Card>{variants([['correction','Needs correction']])}<Notice>No application was submitted from this design preview. Review times are not guaranteed.</Notice></>;action=<Primary onClick={()=>go(variant==='correction'?'documents':'support')}>{variant==='correction'?'Update document':'Contact support'}</Primary>}
 if(isHome){const online=screen==='online';content=<><div className="rd-greeting"><div><span className="rd-kicker">LET’S MAKE IT A GOOD DAY</span><h1>Hi Rahul <span>✦</span></h1><button className="rd-zone-button" onClick={()=>go('readiness')}><MapPin size={13}/>{zone}, Hyderabad<ChevronDown size={13}/></button></div><div className="rd-avatar"><img src="/rider/rider-hero.png" alt="Rahul rider illustration"/></div></div><div className={'rd-status-card '+(online?'online':'')}><span className="rd-status-orb"><span/></span><div><strong>{online?variant==='paused'?'Location paused':'You’re online':'You’re offline'}</strong><p>{online?variant==='paused'?'Restore location to receive orders.':'Looking for nearby orders.':'Ready when you are. Let’s get moving.'}</p></div><button className={'rd-toggle '+(online?'on':'')} aria-label={online?'Go offline':'Go online'} onClick={()=>go(online?'home':'readiness')}><span/></button></div><div className="rd-section-line"><h2>Today, so far</h2><button onClick={()=>go('earnings')}>View earnings <ArrowUpRight size={13}/></button></div><div className="rd-earnings-card"><div><span>YOUR EARNINGS</span><strong>₹360<span>.00</span></strong><small><span className="rd-mini-check"><Check size={10}/></span> ₹270 available · ₹90 pending</small></div><div className="rd-mini-chart">{[23,37,31,50,44,65,56].map((h,i)=><motion.i key={i} initial={{height:0}} animate={{height:h}} transition={{delay:i*.07,duration:.5}}/>)}</div><PawPrint className="rd-earnings-paw" size={88}/></div><div className="rd-stat-pair"><Card><span className="rd-stat-icon"><Package size={18}/></span><strong>8 <small>deliveries</small></strong><span>Completed today</span></Card><Card><span className="rd-stat-icon"><Clock3 size={18}/></span><strong>3<small> h </small>20<small> m</small></strong><span>Time online</span></Card></div><div className="rd-section-line"><h2>Your neighborhood</h2><Badge tone="muted">{zone}</Badge></div><RouteMap/><div className="rd-care-note"><span><Heart size={18}/></span><div><strong>Good deliveries start with you.</strong><p>Check your bag, charge your phone, and ride at your own pace.</p></div></div>{online?<><button className="rd-secondary" onClick={()=>go('offer')}><Package size={18}/>Preview a delivery offer <ArrowRight size={16}/></button>{variants([['paused','Location access interrupted']])}{variant==='paused'&&<Notice tone="amber"><button onClick={settings}>Open settings to restore location</button></Notice>}</>:null}<p className="rd-data-note">All amounts, distances and delivery activity are illustrative.</p></>}
 if(screen==='readiness'){content=<><Heading eyebrow="A GOOD START MAKES A GOOD RIDE" title="Ready, set, ride." description="A quick check before you head out."/><label className="rd-field">Delivery zone<select value={zone} onChange={e=>setZone(e.target.value)}><option>Madhapur</option><option>Kondapur</option><option>Gachibowli</option></select></label><Card><Row icon={<MapPin size={19}/>} title="Location access" detail="Used to find pickups near you." aside={<Badge tone={locationStatus==='Allowed'?'green':'amber'}>{locationStatus}</Badge>}/><button className="rd-secondary" onClick={location}>Allow location <Navigation size={16}/></button>{locationStatus.includes('unavailable')&&<button className="rd-text-button" onClick={settings}>Open settings</button>}<Row icon={<Bell size={19}/>} title="Order notifications" detail={notifications} onClick={async()=>{if(!('Notification' in window)){setNotifications('Unavailable in this browser');return}setNotifications(await Notification.requestPermission())}}/></Card><div className="rd-section-line"><h2>A couple of essentials</h2></div><Card><CheckRow checked={checks.includes('bag')} onChange={()=>toggle('bag')} title="Delivery bag is ready" detail="Clean, secure, and suitable for pet products."/><CheckRow checked={checks.includes('battery')} onChange={()=>toggle('battery')} title="Phone is charged" detail="Enough battery for maps and support."/></Card><Notice><ShieldCheck size={17}/> Stop somewhere safe before using the app.</Notice><p className="rd-data-note">Starting here previews the online state. Live dispatch is not connected.</p></>;action=<Primary disabled={!checks.includes('bag')||!checks.includes('battery')||locationStatus!=='Allowed'} onClick={()=>go('online')}>Start accepting orders</Primary>}
 if(screen==='offer'){content=<><RouteMap route/><Heading eyebrow="A LITTLE CARE, READY TO GO" title="A new delivery for you." description="Review the route and earnings before you accept."/><Card>{orderTop}<RouteStops/><div className="rd-order-facts"><span><Package size={15}/>2 items</span><span><Route size={15}/>4.0 km total</span></div></Card><div className="rd-offer-pay"><span>Estimated earnings<strong>₹45<span>.00</span></strong></span><button onClick={()=>showInfo('Your earnings, clearly',earningsBreakdown)}>See breakdown <ChevronRight size={16}/></button></div>{variants([['expired','Offer expired']])}{variant==='expired'&&<Notice tone="amber">This offer is no longer available. Another rider may have accepted it.</Notice>}</>;action=<><Primary disabled={variant==='expired'} onClick={()=>go('accepted')}>Accept delivery</Primary><button className="rd-bottom-link" onClick={()=>{go('online');setToast('Offer declined. Looking for another delivery.')}}>{variant==='expired'?'Back to online':'Decline offer'}</button></>}
 if(screen==='accepted'){content=<><Heading title="A happy doorstep awaits." description="Your pickup is at Happy Paws Pet Store."/><Progress step={0}/><Card>{orderTop}<RouteStops/><div className="rd-divider"/>{order.items.map((item,i)=><Row key={item.name} icon={i===0?<Package size={20}/>:<PawPrint size={20}/>} title={item.name} detail={item.detail}/>)}</Card><Notice tone="green"><CheckCircle2 size={17}/> Prepaid · no cash collection required</Notice><div className="rd-summary-row"><span>Estimated earnings</span><b>₹45.00</b></div><div className="rd-inline-actions"><button onClick={()=>call('store')}><Phone size={16}/>Call store</button><button onClick={()=>go('pickup-issue')}><AlertTriangle size={16}/>Report a problem</button></div></>;action=<Primary onClick={()=>go('navigation')}>Navigate to store</Primary>}
 if(screen==='navigation'){content=<><RouteMap route large/><div className="rd-map-route-summary"><span><Navigation size={19}/>1.2 km</span><span><Clock3 size={19}/>About 6 min</span></div><Heading eyebrow="PICKUP · PM-2048" title="Happy Paws Pet Store" description={order.storeAddress}/><Notice>Estimated travel time is illustrative. Take your time and follow road rules.</Notice><div className="rd-inline-actions"><button onClick={()=>maps(order.storeAddress)}><Navigation size={17}/>Open navigation</button><button onClick={()=>call('store')}><Phone size={17}/>Call store</button></div></>;action=<Primary onClick={()=>go('pickup')}>I’ve arrived</Primary>}
 if(screen==='pickup'||screen==='medicine'){const medicine=screen==='medicine';const keys=medicine?['seal','label','condition']:['food','toy','condition'];const ready=keys.every(k=>checks.includes(k));content=<><Heading eyebrow={medicine?'PHARMACY ORDER PM-2056':'PICKUP · PM-2048'} title={medicine?'PetCare Pharmacy':'Everything in the bag?'} description={medicine?'Kondapur · 1 sealed package':'Happy Paws Pet Store, Madhapur'}/><Progress step={1}/>{medicine?<><Notice tone={variant==='cleared'?'green':'amber'}><ShieldCheck size={18}/>{variant==='cleared'?'Merchant clearance received · preview':'Waiting for pharmacy clearance'}</Notice><Card><h2>Merchant handling instructions</h2><p>Keep the sealed package dry and upright. Do not open or separate the contents.</p><CheckRow checked={checks.includes('seal')} onChange={()=>toggle('seal')} title="Seal is intact"/><CheckRow checked={checks.includes('label')} onChange={()=>toggle('label')} title="Order label matches PM-2056"/></Card>{variants([['cleared','Merchant clearance received']])}<Notice>The pharmacy handles prescription checks. You only verify the sealed package and order label.</Notice></>:<><Card><div className="rd-section-line"><h2>Order items</h2><Badge tone="muted">2 items</Badge></div><CheckRow checked={checks.includes('food')} onChange={()=>toggle('food')} title="Adult Dog Food · 3 kg" detail="Quantity: 1 pack"/><CheckRow checked={checks.includes('toy')} onChange={()=>toggle('toy')} title="Chew Toy" detail="Quantity: 1 piece"/></Card><button className="rd-secondary" onClick={()=>showInfo('Verify package code',<><ScanLine size={42}/><p>Camera scanning is not connected in this preview. You can check the printed order number instead.</p><label className="rd-field">Package order number<input placeholder="PM-2048" onChange={e=>{if(e.target.value.trim().toUpperCase()==='PM-2048')setChecks(p=>[...new Set([...p,'code'])])}}/></label><Notice>Match PM-2048 on both the app and the store package.</Notice></>)}><ScanLine size={19}/>Scan package code</button><details className="rd-details"><summary>Verify manually instead</summary><CheckRow checked={checks.includes('code')} onChange={()=>toggle('code')} title="Package label matches PM-2048" detail="Read the order number on the package."/></details></>}<Card><CheckRow checked={checks.includes('condition')} onChange={()=>toggle('condition')} title="Package is sealed and undamaged" detail="No leaks, tears, or broken seals."/></Card><details className="rd-details"><summary>Something doesn’t look right?</summary><p>Don’t confirm pickup if an item is missing or damaged.</p><button className="rd-text-button" onClick={()=>go('pickup-issue')}>Report a pickup problem <ArrowRight size={14}/></button></details></>;action=<Primary disabled={!ready||(!medicine&&!checks.includes('code'))||(medicine&&variant!=='cleared')} onClick={()=>{if(medicine){notConnected('Pharmacy pickup');return}go('delivery')}}>{medicine&&variant!=='cleared'?'Waiting for pharmacy clearance':'Confirm pickup'}</Primary>}
 if(screen==='pickup-issue'||screen==='exception'){const issueDelivery=screen==='exception';const reasons=issueDelivery?deliveryReasons:pickupReasons;content=<><Heading eyebrow={'ORDER '+order.id} title={submitted?'Your report is ready.':issueDelivery?'Let’s sort this out.':'What’s happening at pickup?'} description={submitted?'This is a local design preview. A support ticket has not been sent.':'Choose the issue that best describes the situation.'}/>{submitted?<><div className="rd-status-illustration"><Headphones size={40}/></div><Card><Row icon={<FileText size={18}/>} title={reason} detail={notes||'No additional notes'}/></Card><Notice tone="amber">Keep the package secure. A live support team would confirm the next steps. The order remains unresolved.</Notice></>:<><div className="rd-reason-list">{reasons.map(r=><button className={reason===r?'selected':''} key={r} onClick={()=>setReason(r)}>{r}<span>{reason===r&&<Check size={13}/>}</span></button>)}</div><UploadCard title="Add a photo" description="Optional · include the package, not personal details."/><label className="rd-field">Additional notes <small>(optional)</small><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Anything else we should know?" maxLength={500}/></label>{reason&&<Notice>{reason==='Store closed'?'Check the store entrance and contact support. Do not mark the order picked up.':reason==='Customer unavailable'?'Try protected calling or messaging, then contact support. Do not leave the package without authorization.':'Keep the order status unchanged and contact support for instructions.'}</Notice>}</>}{issueDelivery&&<>{variants([['return','Return assigned'],['submitted','Support reviewing']])}{variant==='return'&&<Card><Badge tone="amber">Return assigned · sample</Badge><h2>Happy Paws Pet Store</h2><p>{order.storeAddress}</p><button className="rd-secondary" onClick={()=>maps(order.storeAddress)}>Navigate to return location <Navigation size={16}/></button></Card>}{variant==='submitted'&&<Notice tone="amber">Support reviewing · attempted contact: 1 call, 1 message. Order not completed.</Notice>}</>}<button className="rd-text-button" onClick={()=>go('support')}><Headphones size={16}/> Contact support</button></>;action=!submitted?<Primary disabled={!reason} onClick={()=>setSubmitted(true)}>Review report</Primary>:<Primary onClick={()=>go('support')}>Contact support</Primary>}
 if(screen==='delivery'){content=<><RouteMap route large/><div className="rd-map-route-summary"><span><Navigation size={18}/>2.8 km</span><span><Clock3 size={18}/>About 12 min</span></div><Heading eyebrow="DELIVER TO · PM-2048" title="Ananya R." description={order.customerAddress}/><Card className="rd-instructions"><span className="rd-kicker">A NOTE FROM THE CUSTOMER</span><p>Use the main gate. Building B, third floor. Please call when you arrive.</p></Card><Notice tone="green"><CheckCircle2 size={16}/> Prepaid — no collection required</Notice><div className="rd-inline-actions"><button onClick={()=>call('customer')}><Phone size={17}/>Call customer</button><button onClick={()=>showInfo('Message Ananya',<MessageForm onSend={()=>notConnected('Customer message')}/>)}><MessageCircle size={17}/>Message</button><button onClick={()=>maps(order.customerAddress)}><Navigation size={17}/>Navigate</button></div></>;action=<Primary onClick={()=>go('handover')}>Reached customer</Primary>}
 if(screen==='handover'){content=<><div className="rd-auth-symbol"><Package size={36}/><span><Heart size={13}/></span></div><Heading eyebrow="HANDOVER · PM-2048" title="A little happiness, delivered." description="Confirm the handover with Ananya R."/><Card><Row icon={<Home size={19}/>} title="Ananya R. · Kondapur" detail="Flat 302, Green Valley Apartments"/><div className="rd-divider"/><Row icon={<Package size={19}/>} title="2 packages" detail="Adult Dog Food 3 kg + Chew Toy"/></Card><label className="rd-field">Delivery OTP</label><OTPInput value={handoverOtp} onChange={setHandoverOtp} label="Delivery OTP"/><p className="rd-hint">Ask the customer for the code shown in their order. Don’t use your sign-in OTP.</p>{formError&&<Notice tone="red"><span role="alert">{formError}</span></Notice>}<div className="rd-inline-actions"><button onClick={()=>{setReason('Customer unavailable');go('exception')}}>Customer unavailable</button><button onClick={()=>go('support')}>OTP issue</button></div><Notice>Proof-of-delivery photos are not enabled for this order.</Notice></>;action=<Primary disabled={!/^\d{6}$/.test(handoverOtp)} onClick={()=>setFormError('Delivery verification needs the live order service. No delivery was marked complete.')}>Verify and complete delivery</Primary>}
 if(screen==='cash'){content=<><Heading eyebrow="CASH ORDER PM-2062 · SEPARATE SAMPLE" title="Collect from customer." description="Ravi S. · Gachibowli"/><div className="rd-cash-amount"><span>AMOUNT DUE</span><strong>₹649<span>.00</span></strong><Badge tone={cashConfirmed?'green':'amber'}>{cashConfirmed?'Cash recorded · preview':'Collection pending'}</Badge></div><Notice>Customer payment is not your earnings. Your rider earnings for this order are ₹50.</Notice><div className="rd-segment">{['Cash','Digital payment'].map(m=><button key={m} className={paymentMethod===m?'active':''} onClick={()=>{setPaymentMethod(m);setCashConfirmed(false)}}>{m}</button>)}</div>{paymentMethod==='Cash'?<Card><Row icon={<IndianRupee size={20}/>} title="Collect exactly ₹649" detail="Count the amount with the customer."/></Card>:<><Notice tone={variant==='confirmed'?'green':'amber'}>{variant==='confirmed'?'Confirmed payment layout · illustrative only':'Awaiting confirmation from the payment service.'}</Notice><p className="rd-hint">A payment screenshot is not confirmation. Wait for the payment service to verify receipt.</p>{variants([['confirmed','Confirmed state preview']])}</>}{cashConfirmed&&<Notice tone="green">Cash collection review completed locally. No real payment record was created.</Notice>}</>;action=<Primary disabled={paymentMethod!=='Cash'||cashConfirmed} onClick={()=>showInfo('Confirm cash collection',<><div className="rd-review-amount">₹649.00</div><p>Have you counted and received the full cash amount from Ravi S. for PM-2062?</p><Primary onClick={()=>{setCashConfirmed(true);setPanel(null)}}>Yes, record cash in preview</Primary><button className="rd-bottom-link" onClick={()=>setPanel(null)}>Go back and check</button></>)}>Confirm cash collected</Primary>}
 if(screen==='completed'){content=<div className="rd-completed"><motion.div className="rd-success-ring" initial={{scale:.5,opacity:0}} animate={{scale:1,opacity:1}} transition={{type:'spring',stiffness:220,damping:15}}><Check size={42}/><PawPrint size={15}/></motion.div><Heading eyebrow="ONE MORE HAPPY DOORSTEP" title="Delivery completed." description="Thanks for delivering a little care."/><div className="rd-receipt"><div><span>ORDER</span><b>PM-2048</b></div><div><span>COMPLETED AT</span><b>2:42 PM · sample</b></div><div className="rd-divider"/>{earningsBreakdown}<Badge>₹45 confirmed · sample</Badge></div><p className="rd-hint">Completion screen preview. No live delivery has been completed.</p><button className="rd-text-button" onClick={()=>showInfo('Delivery PM-2048',<DeliveryDetail/>)}>View delivery details <ArrowUpRight size={16}/></button></div>;action=<Primary onClick={()=>go('online')}>Find next delivery</Primary>}
 if(screen==='deliveries'){const entries=[{id:'PM-2036',name:'Pawfect Essentials',area:'Kondapur',date:'2026-10-29',earnings:45,status:'Completed',time:'1:18 PM',category:'Pet food'},{id:'PM-2031',name:'Happy Paws Pet Store',area:'Madhapur',date:'2026-10-29',earnings:50,status:'Completed',time:'12:42 PM',category:'Accessories'},{id:'PM-2025',name:'PetCare Pharmacy',area:'Kondapur',date:'2026-10-28',earnings:40,status:'Completed',time:'11:56 AM',category:'Sealed medicines'},{id:'PM-2019',name:'Happy Paws Pet Store',area:'Madhapur',date:'2026-10-29',earnings:0,status:'Cancelled',time:'11:10 AM',category:'Pet food'},{id:'PM-2012',name:'Pawfect Essentials',area:'Madhapur',date:'2026-10-29',earnings:25,status:'Returned',time:'10:30 AM',category:'Accessories'}];const visible=variant==='empty'?[]:entries.filter(e=>e.status===statusFilter&&(historyFilter==='Today'?e.date==='2026-10-29':historyFilter==='This week'?e.date>='2026-10-23':(!dateFrom||e.date>=dateFrom)&&(!dateTo||e.date<=dateTo)));content=<><Heading eyebrow="EVERY DELIVERY HAS A STORY" title="Your deliveries." description="A little care, one order at a time."/><div className="rd-segment">{['Today','This week','Custom dates'].map(f=><button key={f} className={historyFilter===f?'active':''} onClick={()=>setHistoryFilter(f)}>{f}</button>)}</div>{historyFilter==='Custom dates'&&<div className="rd-form-pair"><label className="rd-field">From<input type="date" value={dateFrom} max={dateTo} onChange={e=>setDateFrom(e.target.value)}/></label><label className="rd-field">To<input type="date" value={dateTo} min={dateFrom} onChange={e=>setDateTo(e.target.value)}/></label></div>}<div className="rd-filter-chips">{['Completed','Cancelled','Returned'].map(f=><button key={f} className={statusFilter===f?'active':''} onClick={()=>setStatusFilter(f)}>{f}</button>)}</div><div className="rd-section-line"><h2>{statusFilter}</h2><span>{visible.length} sample orders</span></div>{visible.map(e=><button className="rd-history-card" key={e.id} onClick={()=>showInfo('Delivery '+e.id,<DeliveryDetail id={e.id} earnings={e.earnings} status={e.status} store={e.name} area={e.area}/>)}><div><span className="rd-history-store"><Store size={20}/></span><section><strong>{e.name}</strong><small>{e.id} · {e.date.slice(8)} Oct · {e.time}</small></section><b>{money(e.earnings)}</b></div><div><span>{e.category} · {e.area}</span><Badge tone={e.status==='Completed'?'green':e.status==='Cancelled'?'red':'amber'}>{e.status}</Badge></div></button>)}{!visible.length&&<Empty icon={<Package size={33}/>} title="Nothing here just yet." text="Your deliveries will appear here when they match the selected filters."/>}{variants([['empty','Empty history']])}<p className="rd-data-note">Sample records dated 23–29 October 2026. Filters apply to these example records.</p></>}
 if(screen==='earnings'){const total=earningsPeriod==='Today'?360:earningsPeriod==='Week'?2340:9360;content=<><Heading eyebrow="THE GOOD IN EVERY RIDE" title="Every ride adds up." description="Your effort, clearly accounted for."/><div className="rd-segment">{['Today','Week','Month'].map(p=><button key={p} className={earningsPeriod===p?'active':''} onClick={()=>setEarningsPeriod(p)}>{p}</button>)}</div><div className="rd-total-earnings"><span>TOTAL EARNINGS</span><strong>{money(total)}</strong><p><Package size={15}/>{earningsPeriod==='Today'?8:earningsPeriod==='Week'?52:208} completed deliveries</p><div className="rd-chart" aria-label="Illustrative daily earnings bar chart">{[42,65,50,83,61,95,75].map((h,i)=><div key={i}><motion.i initial={{height:0}} animate={{height:h}} transition={{duration:.5,delay:i*.06}}/><small>{['M','T','W','T','F','S','S'][i]}</small></div>)}</div></div><div className="rd-balance-grid"><Card><span>Available</span><b>₹270</b><i className="green"/></Card><Card><span>Pending</span><b>₹90</b><i className="amber"/></Card><Card><span>Paid out</span><b>₹1,980</b><i/></Card></div><Card className="rd-breakdown"><div><span>Delivery earnings</span><b>{money(total)}</b></div><div><span>Tips</span><b>₹0.00</b></div><div><span>Adjustments</span><b>₹0.00</b></div></Card><div className="rd-section-line"><h2>Latest activity</h2><button onClick={()=>go('payouts')}>View payouts <ArrowUpRight size={14}/></button></div><Card>{[['PM-2036','Delivery earnings','₹45'],['PM-2031','Delivery earnings','₹50'],['PM-2025','Processing','₹40']].map(([id,label,amount])=><Row key={id} icon={<Wallet size={18}/>} title={id} detail={label} aside={<b>{amount}</b>}/>)}</Card><button className="rd-text-button" onClick={()=>go('support')}>Something doesn’t add up? Get help</button><p className="rd-data-note">Illustrative earnings, not a live account balance.</p></>}
 if(screen==='payouts'){content=<><Heading eyebrow="FROM YOUR RIDES TO YOUR ACCOUNT" title="Your payouts."/><div className="rd-total-earnings"><span>AVAILABLE BALANCE</span><strong>₹270<span>.00</span></strong><p>Pending earnings: ₹90.00</p></div><Card><Row icon={<CreditCard size={20}/>} title="Bank account •••• 4821" detail="Rahul Kumar · sample account"/><Notice>Next scheduled payout will appear when confirmed. No date is currently available.</Notice></Card><div className="rd-section-line"><h2>Payout history</h2><Badge tone="muted">Sample records</Badge></div>{[['₹270','Pending','Awaiting schedule','PAY-1048'],['₹450','Processing','27 Oct 2026','PAY-1045'],['₹1,980','Paid','24 Oct 2026','PAY-1039'],['₹180','Failed','22 Oct 2026','PAY-1034']].map(([amt,status,date,ref])=><Card key={ref}><div className="rd-payout-row"><span className="rd-row-icon"><Wallet size={19}/></span><span><strong>{amt}</strong><small>{date}</small></span><Badge tone={status==='Paid'?'green':status==='Failed'?'red':'amber'}>{status}</Badge></div><div className="rd-payout-ref">Reference {ref}{status==='Failed'&&<button onClick={()=>go('support')}>Get help</button>}</div></Card>)}<Notice>Withdrawals are not enabled. Available earnings follow the account’s payout schedule.</Notice></>}
 if(screen==='notifications'){const inbox=[['order','Your pickup is ready','Happy Paws has packed order PM-2048.','10 min ago','accepted'],['document','Document update','Your vehicle document needs a clearer photo.','1 hr ago','documents'],['payout','Payout received','₹1,980 transferred to account •••• 4821.','24 Oct','payouts'],['support','A reply from rider support','Your account question has an update.','23 Oct','support']];content=<><Heading title="Stay in the loop." description="The updates that matter to your day."/>{variants([['empty','Empty inbox']])}{variant==='empty'?<Empty icon={<Bell size={34}/>} title="All caught up." text="Your order and account updates will appear here."/>:inbox.map(([id,t,d,time,dest],i)=><div key={id}>{(i===0||i===2)&&<div className="rd-section-line"><h2>{i===0?'Today':'Earlier'}</h2></div>}<button className={'rd-notification '+(!read.includes(id)?'unread':'')} onClick={()=>{setRead(p=>[...p,id]);go(dest as Screen)}}><span className="rd-row-icon">{i===0?<Package size={19}/>:i===1?<FileText size={19}/>:i===2?<Wallet size={19}/>:<Headphones size={19}/>}</span><div><strong>{t}</strong><p>{d}</p><small>{time} · illustrative update</small></div>{!read.includes(id)&&<i/>}</button></div>)}<button className="rd-text-button" onClick={()=>showInfo('Notification preferences',<Preferences/>)}><Settings size={16}/>Notification preferences</button></>}
 if(screen==='support'){content=<><Heading eyebrow="YOU DON’T HAVE TO FIGURE IT OUT ALONE" title="We’ve got your back." description="Let’s get you to the right help."/><div className="rd-support-current"><span><Package size={20}/></span><div><small>CURRENT ORDER</small><strong>PM-2048 · Happy Paws</strong></div><Badge tone="amber">In progress</Badge></div><Card><Row icon={<Package size={21}/>} title="Current delivery issue" detail="Pickup, handover, or customer unavailable" onClick={()=>go('exception')}/><Row icon={<Wallet size={21}/>} title="Payment issue" detail="Earnings, collections, or payouts" onClick={()=>showInfo('Payment support',<MessageForm onSend={m=>{setSupportMessages(p=>[...p,m]);setPanel(null);setToast('Message drafted locally; not sent.')}}/>)}/><Row icon={<ShieldCheck size={21}/>} title="Account verification" detail="Documents or application status" onClick={()=>go('application')}/></Card><button className="rd-safety-card" onClick={()=>showInfo('Safety assistance',<><Notice tone="red">If you’re in immediate danger, move to a safe place and contact local emergency services.</Notice><p>In-app safety calling is not connected. Stop riding before using your phone.</p><button className="rd-secondary" onClick={()=>call('support')}>Rider support availability <Phone size={16}/></button></>)}><span><ShieldCheck size={23}/></span><div><strong>Safety assistance</strong><p>Your wellbeing comes first.</p></div><ChevronRight size={19}/></button><div className="rd-inline-actions"><button onClick={()=>showInfo('Chat with rider support',<MessageForm onSend={m=>{setSupportMessages(p=>[...p,m]);setPanel(null);setToast('Draft saved for this visit. Support is not connected.')}}/>)}><MessageCircle size={18}/>Support chat</button><button onClick={()=>call('support')}><Phone size={18}/>Call availability</button></div><div className="rd-section-line"><h2>Your support requests</h2></div>{supportMessages.length?supportMessages.map((m,i)=><Card key={i}><Badge tone="muted">Local draft · not sent</Badge><p>{m}</p></Card>):<Card><Row icon={<MessageCircle size={18}/>} title="Earnings question" detail="Sample ticket #SUP-102 · resolved" aside={<Badge>Resolved</Badge>}/></Card>}</>}
 if(screen==='profile'){content=<><div className="rd-profile-hero"><div className="rd-avatar"><img src="/rider/rider-hero.png" alt="Rahul rider illustration"/></div><h1>{name}</h1><p>Rider ID PM-R1042 · sample</p><Badge><ShieldCheck size={12}/>Verified profile · sample</Badge><span><MapPin size={13}/>{zone}, Hyderabad</span></div><Card><Row icon={<UserRound size={18}/>} title="Personal details" detail="Your name and contact details" onClick={()=>go('registration')}/><Row icon={<Bike size={18}/>} title="Vehicle details" detail={vehicle+' · •••• 4821'} onClick={()=>showInfo('Your vehicle',<><Notice>{vehicle} · registration •••• 4821 · sample</Notice><p>Vehicle details are reviewed with your application.</p><Primary onClick={()=>go('registration')}>Update vehicle type</Primary></>)}/><Row icon={<FileText size={18}/>} title="Documents" detail="Identity and vehicle documents" onClick={()=>go('documents')}/><Row icon={<CreditCard size={18}/>} title="Payout account" detail="Bank account ending •••• 4821" onClick={()=>go('payouts')}/></Card><Card><Row icon={<Globe size={18}/>} title="Language" detail={language} onClick={()=>showInfo('Preferred language',<label className="rd-field">Language<select defaultValue={language} onChange={e=>{setLanguage(e.target.value);setToast('Language preference updated. Preview copy remains English.')}}><option>English</option><option>Telugu</option><option>Hindi</option></select></label>)}/><Row icon={<Bell size={18}/>} title="Notification preferences" onClick={()=>showInfo('Notification preferences',<Preferences/>)}/><Row icon={<LockKeyhole size={18}/>} title="Privacy" onClick={()=>showInfo('Your privacy',<p>Your design-preview documents, bank inputs and OTPs are not written to browser storage. Real sign-in uses Firebase. Operational data remains illustrative.</p>)}/></Card><button className="rd-logout" onClick={()=>showInfo('Log out of PetMeta Rider?',<><p>You can sign in again using your email and password.</p><Primary onClick={async()=>{await signOut(auth);setPassword('');setBank({holder:'',account:'',confirm:'',ifsc:''});go('login')}}>Log out</Primary></>)}><LogOut size={17}/>Log out</button><p className="rd-data-note">PetMeta Rider · Design v1.0<br/>{signedIn?'Firebase signed in':'Design preview · not signed in'}</p></>}
 if(screen==='home')action=<Primary onClick={()=>go('readiness')}>Go online <span className="rd-button-dot"/></Primary>;
 return <div className={'rd-app '+(screen==='splash'?'rd-yellow-screen':'')}>
  <div className="rd-statusbar"><span>9:41</span><div><Signal size={13}/><Wifi size={13}/><BatteryFull size={18}/></div></div>
  <header className="rd-app-header">{isHome?<><div className="rd-app-brand"><img src="/logo.jpg" alt="PetMeta"/><b>RIDER</b></div><button aria-label="Notifications" className="rd-icon-button rd-bell" onClick={()=>go('notifications')}><Bell size={20}/><i/></button></>:screen==='splash'?<span/>:<><button className="rd-icon-button" aria-label="Back" onClick={()=>{const i=screens.findIndex(s=>s[0]===screen);go(screens[Math.max(0,i-1)][0])}}><ArrowLeft size={20}/></button><span>{onboarding.includes(screen)?'PetMeta Rider':screen==='earnings'?'Earnings':screen==='deliveries'?'Deliveries':screen==='profile'?'My profile':title}</span><button className="rd-icon-button" aria-label="Rider support" onClick={()=>go('support')}><Headphones size={19}/></button></>}</header>
  <div className="rd-preview-disclosure"><span/>DESIGN PREVIEW · SAMPLE DATA</div>
  <div className="rd-app-scroll" ref={scroll}><AnimatePresence mode="wait" initial={false}><motion.div className="rd-screen-content" key={screen} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.22,ease:'easeOut'}}>{content}</motion.div></AnimatePresence></div>
  {action&&<div className="rd-bottom-action">{action}</div>}
  {mainNav&&<nav className="rd-bottom-nav">{[{icon:Home,id:'home',label:'Home'},{icon:Package,id:'deliveries',label:'Deliveries'},{icon:Wallet,id:'earnings',label:'Earnings'},{icon:UserRound,id:'profile',label:'Profile'}].map(({icon:I,id,label})=>{const active=screen===id||(id==='home'&&screen==='online')||(id==='earnings'&&screen==='payouts');return <button key={id} className={active?'active':''} onClick={()=>go(id as Screen)}><span><I size={20}/></span><small>{label}</small>{active&&<motion.i layoutId="rd-nav-indicator"/>}</button>})}</nav>}
  <AnimatePresence>{toast&&<motion.div role="status" className="rd-toast" initial={{y:20,opacity:0}} animate={{y:0,opacity:1}} exit={{opacity:0}}><Check size={16}/>{toast}</motion.div>}</AnimatePresence>
  <AnimatePresence>{panel&&<motion.div className="rd-modal-backdrop" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={()=>setPanel(null)}><motion.section className="rd-sheet" role="dialog" aria-modal="true" aria-label={panel.title} initial={{y:120}} animate={{y:0}} exit={{y:120}} transition={{type:'spring',damping:30,stiffness:320}} onClick={e=>e.stopPropagation()} onKeyDown={e=>{if(e.key==='Escape')setPanel(null);if(e.key==='Tab'){const targets=e.currentTarget.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,textarea,a[href]');const first=targets[0],last=targets[targets.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}}><div className="rd-sheet-handle"/><div className="rd-sheet-heading"><h2>{panel.title}</h2><button autoFocus aria-label="Close dialog" onClick={()=>setPanel(null)}><X size={20}/></button></div><div className="rd-sheet-content">{panel.content}</div></motion.section></motion.div>}</AnimatePresence>
 </div>
}
function Empty({icon,title,text}:{icon:ReactNode;title:string;text:string}){return <div className="rd-empty"><span>{icon}</span><h2>{title}</h2><p>{text}</p></div>}
function MessageForm({onSend}:{onSend:(m:string)=>void}){const [message,setMessage]=useState('');return <form className="rd-message-form" onSubmit={e=>{e.preventDefault();if(message.trim())onSend(message.trim())}}><label className="rd-field">Your message<textarea required maxLength={500} placeholder="Tell us how we can help…" value={message} onChange={e=>setMessage(e.target.value)}/></label><Notice>Preview only. Messages are not sent to a customer or support team.</Notice><Primary type="submit" disabled={!message.trim()}>Save message draft</Primary></form>}
function Preferences(){const [order,setOrder]=useState(true);const [payout,setPayout]=useState(true);const [news,setNews]=useState(false);return <><CheckRow checked={order} onChange={()=>setOrder(!order)} title="Order updates" detail="Pickup and delivery changes"/><CheckRow checked={payout} onChange={()=>setPayout(!payout)} title="Payout updates" detail="Transfer and earnings updates"/><CheckRow checked={news} onChange={()=>setNews(!news)} title="Rider announcements" detail="Optional news from PetMeta"/><Notice>Preferences apply to this preview session only.</Notice></>}
function DeliveryDetail({id='PM-2048',earnings=45,status='Completed',store='Happy Paws Pet Store',area='Madhapur'}:{id?:string;earnings?:number;status?:string;store?:string;area?:string}){const events=status==='Cancelled'?['Accepted','Cancelled before pickup']:['Accepted','At store','Picked up',status];return <><Badge tone={status==='Completed'?'green':'amber'}>{status} · sample</Badge>{id==='PM-2048'?<RouteStops/>:<Row icon={<Store size={19}/>} title={store} detail={area+' · Hyderabad'}/>}<div className="rd-timeline">{events.map((t,i)=><div key={t}><Check size={12}/><span>{t} · {['2:05','2:12','2:17','2:42'][i]} PM</span></div>)}</div><div className="rd-breakdown"><div><span>Order</span><b>{id}</b></div><div><span>{status==='Cancelled'?'Distance before cancellation':'Total distance'}</span><b>{status==='Cancelled'?'0.0':'4.0'} km</b></div><div className="rd-breakdown-total"><span>Rider earnings</span><strong>{money(earnings)}</strong></div></div><p className="rd-hint">Illustrative timeline and earnings. Not a live order record.</p></>}


